Description: This Terraform configuration creates a private 2-node Amazon Redshift cluster in a new VPC with two subnets, a subnet group, and a security group. It also attaches an Amazon Redshift resource policy to the cluster using `aws_redshift_resource_policy`. Default variable values are provided so the configuration can be applied directly.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

variable "aws_region" {
  description = "AWS region to deploy the Redshift cluster into."
  type        = string
  default     = "us-east-1"
}

variable "cluster_identifier" {
  description = "Identifier for the Redshift cluster."
  type        = string
  default     = "example-redshift-2-node-cluster"
}

variable "database_name" {
  description = "Initial Redshift database name."
  type        = string
  default     = "devdb"
}

variable "master_username" {
  description = "Master username for the Redshift cluster."
  type        = string
  default     = "adminuser"
